package main

import (
	"bytes"
	"fmt"
)

// out is a file being written.
type out struct{ bytes.Buffer }

func (o *out) line(format string, a ...any) { fmt.Fprintf(o, format+"\n", a...) }

// header starts a generated file of p's package.
func (o *out) header(p *prime) {
	o.line("//go:build gots_overlay\n")
	o.line("// Code generated by _gen. DO NOT EDIT.\n")
	o.line("package %s\n", p.pkg)
}
